    """Tuned Best Fit (lo=8, hi=19, penalty=34): the tightest bin wins, but leaving a gap
    strictly between 8 and 19 units costs 34. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 34 * ((r > 8) & (r < 19))

